import React, { useState } from 'react';
import './Nav.css';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import Button from '../Button/Button';

function Nav() {
    const navigate = useNavigate();
    const location = useLocation();
    const [menuOpen, setMenuOpen] = useState(false);

    const svg = (
        <svg viewBox="0 0 70 36">
            <path d="M6.9739 30.8153H63.0244C65.5269 30.8152 75.5358 -3.68471 35.4998 2.81531C-16.1598 11.2025 0.894099 33.9766 26.9922 34.3153C104.062 35.3153 54.5169 -6.68469 23.489 9.31527" />
        </svg>
    );

    function isActiveLink(path, currentPath) {
        if (path === '/') return currentPath === '/';
        return currentPath === path || currentPath.startsWith(path + '/');
    }

    return (
        <>
            <nav className="nav">
                <div className="nav-container">
                    <div className="nav-infos">
                        <a href="/" className="nav-logo">
                            <img src="/img/logo.png" alt="Mon logo" />
                        </a>
                        <a href="mailto:damienfrugier@yahoo.com" className="nav-mail">damienfrugier@yahoo.com</a>

                        {/* Bouton menu mobile */}
                        <div className="burger" onClick={() => setMenuOpen(!menuOpen)}>
                            <span className={menuOpen ? 'open' : ''}></span>
                            <span className={menuOpen ? 'open' : ''}></span>
                            <span className={menuOpen ? 'open' : ''}></span>
                        </div>
                    </div>

                    {/* Liens de navigation */}
                    <ul className={`nav-links ${menuOpen ? 'show' : ''}`}>
                        {menuOpen && (
                            <li className="nav-logo-mobile">
                                <a href="/" onClick={() => setMenuOpen(false)}>
                                    <img src="/img/logo.png" alt="Mon logo" />
                                </a>
                            </li>
                        )}
                        <li>
                            <Link to="/" className={`link${isActiveLink('/', location.pathname) ? ' active' : ''}`} onClick={() => setMenuOpen(false)}>
                                Accueil {svg}
                            </Link>
                        </li>
                        <li>
                            <Link to="/about" className={`link${isActiveLink('/about', location.pathname) ? ' active' : ''}`} onClick={() => setMenuOpen(false)}>
                                À propos {svg}
                            </Link>
                        </li>
                        <li>
                            <Link to="/services" className={`link${isActiveLink('/services', location.pathname) ? ' active' : ''}`} onClick={() => setMenuOpen(false)}>
                                Services {svg}
                            </Link>
                        </li>
                        <li>
                            <Link to="/portfolio" className={`link${isActiveLink('/portfolio', location.pathname) ? ' active' : ''}`} onClick={() => setMenuOpen(false)}>
                                Projets {svg}
                            </Link>
                        </li>
                        <li>
                            <Button
                                className="button-contact"
                                type="text"
                                onClick={() => {
                                    navigate('/contact');
                                    setMenuOpen(false);
                                }}
                            >Contactez-moi</Button>
                        </li>
                    </ul>
                </div>
            </nav>
            {menuOpen && <div className="overlay" onClick={() => setMenuOpen(false)}></div>}
        </>

    );
}

export default Nav;
