import React, {useState, useEffect} from 'react';
import './Services.css'
import GroupPage from "../../components/GrougPage/GroupPage";
import GroupTitle from '../../components/GroupTitle/GroupTitle';
import ServiceCard from '../../components/ServiceCard/ServiceCard';
import servicesData from '../../data/services';

const Services = () => {
    const [services, setServices] = useState([]);

    useEffect(() => {
        setServices(servicesData);
    }, []);
    return (
        <div className="services__wrapper">
            <GroupPage
                titleCurrentPage="Services"
                linkPath="/services"
                linkText="Mes services"
            />
            <section className="section services">
                <GroupTitle
                    subtitle="Mes services"
                    title="Découvrez"
                    span="tous les services que je propose"
                />
                <div className="services__container">
                    {services.map(service => (
                        <ServiceCard key={service.id} service={service} />
                    ))}
                </div>
            </section>
        </div>
    )
}

export default Services
