import React, { useState, useRef } from 'react';
import emailjs from '@emailjs/browser';
import Swal from 'sweetalert2';
import Input from '../../components/Input/Input';
import GroupTitle from '../../components/GroupTitle/GroupTitle';
import Button from '../../components/Button/Button';
import { FaPhoneAlt } from "react-icons/fa";
import { IoIosMail } from "react-icons/io";
import { IoMdArrowRoundForward } from "react-icons/io";
import { HiMiniMapPin } from "react-icons/hi2";
import Spinner from '../../components/Spinner/Spinner';
import './Contact.css';

const Contact = () => {
    const [form, setForm] = useState({
        lastname: '',
        firstname: '',
        email: '',
        message: ''
    });

    const [errors, setErrors] = useState({});
    const [loading, setLoading] = useState(false);
    const formRef = useRef();

    const handleChange = (e) => {
        setForm({ ...form, [e.target.name]: e.target.value });
        setErrors({ ...errors, [e.target.name]: '' });
    };

    const validate = () => {
        const newErrors = {};
        if (!form.lastname.trim()) newErrors.lastname = 'Nom requis';
        if (!form.firstname.trim()) newErrors.firstname = 'Prénom requis';
        if (!form.email.trim()) {
            newErrors.email = 'Email requis';
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) {
            newErrors.email = 'Email invalide';
        }
        if (!form.message.trim()) newErrors.message = 'Message requis';
        return newErrors;
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        const validationErrors = validate();
        if (Object.keys(validationErrors).length > 0) {
            setErrors(validationErrors);
            return;
        }

        setLoading(true);

        emailjs.sendForm(
            'service_3ulf0yx',
            'template_9q28nzd',
            formRef.current, 
            {
                publicKey: 'qCYNb0WwUYRVjlMVt',
            })
        .then(
            (result) => {
                console.log('SUCCESS!', result.text);
                setLoading(false);
                Swal.fire({
                    icon: 'success',
                    title: 'Message envoyé !',
                    text: 'Merci pour votre message, je vous répondrai bientôt.',
                    confirmButtonColor: '#3085d6'
                });
                setForm({ lastname: '', firstname: '', email: '', message: '' });
            },
            (error) => {
                console.error('FAILED...', error.text);
                setLoading(false);
                Swal.fire({
                    icon: 'error',
                    title: 'Oups...',
                    text: "Une erreur s'est produite. Veuillez réessayer.",
                    confirmButtonColor: '#d33'
                });
            }
        );
    };

    return (
        <div className="contact__wrapper">
            <section className="section contact">
                <div className="contact__left">
                    <GroupTitle
                        subtitle="Contactez-moi"
                        title="Parlons de"
                        span="vos prochains projets"
                    />
                    <p className='contact__description'>N'hésitez pas à me contacter pour discuter de vos idées ou projets.</p>
                    <ul className="contact__links">
                        <li className='link'>
                            <a href="tel:0601020304">
                                <Button className="icon-contact-link" type="icon">
                                    <FaPhoneAlt />
                                </Button>
                                <span>06 01 02 03 04</span>
                            </a>
                        </li>
                        <li className='link'>
                            <a href="mailto:damienfrugier@yahoo.com">
                                <Button className="icon-contact-link" type="icon">
                                    <IoIosMail />
                                </Button>
                                <span>damienfrugier@yahoo.com</span>
                            </a>
                        </li>
                        <li className='link'>
                            <a href="https://maps.app.goo.gl/HgBsLbK7tSWxpVvCA" target='_blank' rel='noreferrer'>
                                <Button className="icon-contact-link" type="icon">
                                    <HiMiniMapPin />
                                </Button>
                                <span>317 Rue de la République, 60280 Margny-lès-Compiègne</span>
                            </a>
                        </li>
                    </ul>
                </div>

                <div className="contact__right">
                    <form ref={formRef} className="contact-form" onSubmit={handleSubmit}>
                        <div className="input-group">
                            <Input
                                label="Nom"
                                placeholder="Entrez votre nom"
                                type="text"
                                name="lastname"
                                value={form.lastname}
                                onChange={handleChange}
                                error={errors.lastname}
                            />
                            <Input
                                label="Prénom"
                                placeholder="Entrez votre prénom"
                                type="text"
                                name="firstname"
                                value={form.firstname}
                                onChange={handleChange}
                                error={errors.firstname}
                            />
                        </div>
                        <Input
                            label="Email"
                            placeholder="exemple@domaine.com"
                            type="email"
                            name="email"
                            value={form.email}
                            onChange={handleChange}
                            error={errors.email}
                        />
                        <div className="input">
                            <label htmlFor="message">Message*</label>
                            <textarea
                                name="message"
                                id="message"
                                placeholder="Votre message..."
                                value={form.message}
                                onChange={handleChange}
                                className={errors.message ? "has-error" : ""}
                            />
                            {errors.message && <span className="input-error">{errors.message}</span>}
                        </div>
                        <div type="submit" className="button-text-icon" disabled={loading}>
                            {loading ? <Spinner /> :
                                <>
                                    <Button className="button-more-portfolio" type="text">
                                        Envoyer
                                    </Button>
                                    <Button className="button-arrow" type="icon">
                                        <IoMdArrowRoundForward />
                                    </Button>
                                </>
                            }
                        </div>
                    </form>
                </div>
            </section>
        </div>
    );
};

export default Contact;
