import React, { useEffect, useState } from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import { motion } from 'framer-motion';
import CV from '../../assets/pdf/CV.pdf';
import './Home.css';
import Button from '../../components/Button/Button';
import { FaLinkedinIn } from "react-icons/fa";
import { FaInstagram } from "react-icons/fa";
import { IoClose } from "react-icons/io5";
import { IoMdArrowRoundForward } from "react-icons/io";
import ServiceCard from '../../components/ServiceCard/ServiceCard';
import servicesData from '../../data/services';
import GroupTitle from '../../components/GroupTitle/GroupTitle';
import { Link } from 'react-router-dom';
import ProjectCard from '../../components/ProjectCard/ProjectCard';
import projectsData from '../../data/projets.json';

const itemVariant = {
    hidden: { x: -50, opacity: 0 },
    visible: (i) => ({
        x: 0,
        opacity: 1,
        transition: {
            delay: i * 0.2,
            duration: 0.6,
            ease: "easeOut"
        }
    }),
};

const Home = () => {
    const [services, setServices] = useState([]);
    const [isDesktop, setIsDesktop] = useState(window.innerWidth >= 1024);
    const [isPhone, setIsPhone] = useState(window.innerWidth < 768);
    const [selectedProject, setSelectedProject] = useState(null);
    const [isModalVisible, setIsModalVisible] = useState(false);

    const openModal = (project) => {
        setSelectedProject(project);
        setTimeout(() => setIsModalVisible(true), 10);
    };

    const closeModal = () => {
        setIsModalVisible(false);
        setTimeout(() => setSelectedProject(null), 400);
    };

    useEffect(() => {
        const handleResize = () => {
            setIsDesktop(window.innerWidth >= 1024);
            setIsPhone(window.innerWidth < 768);
        };

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        setServices(servicesData);
    }, []);
    return (
        <div className="home__wrapper">
            <section className="section home">
                <div className="home__container">
                    <div className="home__presentation">
                        <motion.h3
                            custom={0}
                            initial="hidden"
                            animate="visible"
                            variants={itemVariant}
                        >
                            Damien Frugier
                        </motion.h3>

                        <motion.h1
                            className="home__title"
                            custom={1}
                            initial="hidden"
                            animate="visible"
                            variants={itemVariant}
                        >
                            Chargé de <span>communication</span>
                        </motion.h1>

                        <motion.p
                            className="home__description"
                            custom={2}
                            initial="hidden"
                            animate="visible"
                            variants={itemVariant}
                        >
                            Je me partage entre la municipalité de <a href="https://www.thourotte.fr/fr/" target='_blank' rel="noreferrer">Thourotte</a> et <a href="https://www.sabaicreation.fr" target='_blank' rel="noreferrer">Sabaï Création</a>, la start-up que j'ai co-fondée.
                            Je mets aussi mon inventivité à votre disponsition !
                        </motion.p>

                        <motion.div
                            className="home__social__medias"
                            custom={3}
                            initial="hidden"
                            animate="visible"
                            variants={itemVariant}
                        >
                            <a href={CV} target="_blank" rel="noopener noreferrer">
                                <Button className="button-cv" type="text">
                                    Voir mon CV
                                </Button>
                            </a>
                            <a href="https://www.linkedin.com/in/damien-frugier/" target="_blank" rel="noopener noreferrer">
                                <Button className="button-linkedin" type="icon">
                                    <FaLinkedinIn />
                                </Button>
                            </a>
                            <a href="https://www.instagram.com/damienfrugier/" target="_blank" rel="noopener noreferrer">
                                <Button className="button-instagram" type="icon">
                                    <FaInstagram />
                                </Button>
                            </a>
                        </motion.div>
                    </div>
                    <div className="home__img">
                        <img src="/img/mockup.png" alt="Damien Frugier" />
                    </div>
                </div>
            </section>
            <section className='section services'>
                <div className="services__titles">
                    <GroupTitle
                        subtitle="Mes services"
                        title="Services"
                        span="que je propose"
                    />

                    <Link to="/services" className="button-text-icon">
                        <Button
                            className="button-more-services" type="text"
                        >
                            Voir tous les services
                        </Button>
                        <Button className="button-arrow" type="icon">
                            <IoMdArrowRoundForward />
                        </Button>
                    </Link>

                </div>
                <div className="services__container">
                    {services.slice(0, 3).map(service => (
                        <ServiceCard key={service.id} service={service} />
                    ))}
                </div>
            </section>
            <section className='section about'>
                <div className="about__container">
                    <div className="about__img">
                        <img src="/img/about-img.png" alt="Damien Frugier" />
                    </div>
                    <div className="about__presentation">
                        <GroupTitle
                            subtitle="À propos de moi"
                            title="Qui est"
                            span="Damien Frugier ?"
                        />
                        <p className='about__description'>
                            Depuis 20 ans, je suis chargé de communication de la municipalité de Thourotte, dans l’Oise. En 2025, je suis passé à mi-temps pour co-créer  la start-up Sabaï Création, spécialisée dans l’innovation textile. Pour Thourotte comme pour d’autres commanditaires, j’organise et j’anime des événements.  Je suis ouvert aux missions que vous me proposerez !
                        </p>
                        <Link to="/about" className="button-text-icon">
                            <Button className="button-more-about" type="text">
                                En savoir plus
                            </Button>
                            <Button className="button-arrow" type="icon">
                                <IoMdArrowRoundForward />
                            </Button>
                        </Link>
                    </div>
                </div>
            </section>
            <section className='section portfolio'>
                <div className="portfolio__titles">
                    <GroupTitle
                        subtitle="Mon travail"
                        title="Découvrez"
                        span="mes projets"
                    />
                    <Link to="/portfolio" className="button-text-icon">
                        <Button className="button-more-portfolio" type="text">
                            Voir mon portfolio
                        </Button>
                        <Button className="button-arrow" type="icon">
                            <IoMdArrowRoundForward />
                        </Button>
                    </Link>
                </div>
                <div className="portfolio__container">
                    {isDesktop ? (
                        <div className="grid-view">
                            {projectsData.slice(0, 3).map((project) => (
                                <ProjectCard key={project.id} project={project} onOpen={openModal} />
                            ))}
                        </div>
                    ) : (

                        <Swiper
                            spaceBetween={24}
                            slidesPerView={isPhone ? 1 : 1.5}
                            grabCursor={true}
                            autoHeight={true}
                        >
                            {projectsData.slice(0, 3).map((project) => (
                                <SwiperSlide key={project.id} >
                                    <ProjectCard project={project} onOpen={openModal} />
                                </SwiperSlide>
                            ))}
                        </Swiper>
                    )}
                </div>
            </section>
            <section className='section contact'>
                <div className="contact__container">
                    <div className="contact__container-content">
                        <h2 className='title'>Faisons bouger les choses</h2>
                        <p className='description'>Contactez-nous dès aujourd’hui pour en savoir plus sur la façon dont nos services de marketing numérique peuvent aider votre entreprise à croître et à réussir en ligne.</p>
                        <Link to="/contact" className="button-text-icon">
                            <Button className="button-contact" type="text">
                                Contactez-moi
                            </Button>
                            <Button className="button-arrow" type="icon">
                                <IoMdArrowRoundForward />
                            </Button>
                        </Link>
                    </div>
                    <div className="contact__img">
                        <img src="/img/contact-img.png" alt="Contact Damien Frugier" />
                    </div>
                </div>
            </section>
            {selectedProject && (
                <div className="modal-container">
                    <div className="modal-overlay" onClick={closeModal}></div>
                    <div className={`modal ${isModalVisible ? 'slide-in' : 'slide-out'}`}>
                        <Button
                            className="close-btn"
                            type="icon"
                            onClick={closeModal}
                            aria-label="Fermer la modal"
                        >
                            <IoClose />
                        </Button>
                        <div className="modal-content">
                            <img src={selectedProject.image} alt={selectedProject.title} className="modal-image" />
                            <div className="modal-content-text">
                                <h2 className="modal-title">{selectedProject.title}</h2>
                                <div className="modal-description">{selectedProject.description}</div>
                                <div className="modal-buttons">
                                    <Button onClick={() => window.open(selectedProject.image, '_blank')}>
                                        Ouvrir l'image
                                    </Button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

        </div>
    );
}

export default Home;
