import React, { useState, useEffect, useRef } from 'react';
import './ServiceCard.css';
import Button from '../Button/Button';
import { IoClose } from "react-icons/io5";
import { IoIosCheckmarkCircle } from "react-icons/io";
import { motion, useInView } from 'framer-motion';

const ServiceCard = ({ service }) => {
    const [isVisible, setIsVisible] = useState(false);
    const [isMounted, setIsMounted] = useState(false);

    const openModal = () => {
        setIsMounted(true);
        setTimeout(() => setIsVisible(true), 10);
    };

    const closeModal = () => {
        setIsVisible(false);
        setTimeout(() => setIsMounted(false), 400);
    };

    useEffect(() => {
        if (isMounted) {
            const originalOverflow = document.body.style.overflow;
            document.body.style.overflow = 'hidden';
            return () => {
                document.body.style.overflow = originalOverflow;
            };
        }
    }, [isMounted]);

    // Animation au scroll
    const ref = useRef(null);
    const inView = useInView(ref, { once: true, threshold: 0.2 });

    return (
        <motion.div
            ref={ref}
            className="services__container-card"
            initial={{ opacity: 0, y: 40 }}
            animate={inView ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.6, ease: 'easeOut' }}
        >
            <div className="card-titles">
                <h3 style={{ marginBottom: '0.5rem' }}>{service.title}</h3>
                <p style={{ color: '#555', marginBottom: '1rem' }}>{service.description}</p>
            </div>
            <Button className="view-more-btn" type="text" onClick={openModal}>
                Voir plus
            </Button>

            {isMounted && (
                <div className="modal-container">
                    <div className="modal-overlay" onClick={closeModal}></div>
                    <div className={`modal ${isVisible ? 'slide-in' : 'slide-out'}`}>
                        <Button
                            className="close-btn" type="icon"
                            onClick={closeModal} aria-label="Fermer la modal">
                            <IoClose />
                        </Button>

                        <h2 className='modal-title'>{service.modalTitle}</h2>
                        <p className='modal-description'>{service.modalDescription}</p>
                        <ul className='modal-services-list'>
                            {service.modalServices && service.modalServices.map((item, i) => (
                                <li key={i}>
                                    <span><IoIosCheckmarkCircle className='check-icon' /></span> {item}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
            )}
        </motion.div>
    );
};

export default ServiceCard;
